import React, { Component } from 'react'

import SectionWrapper from './index.style'

class Experience extends Component {
  constructor (props) {
    super(props)
    this.state = {
      currentExperienceSlide: 0
    }
  }

  componentDidMount () {
    let runningSlide = this.state.currentExperienceSlide
    const slide = setInterval(() => {
      if (runningSlide <= 2) {
        runningSlide = runningSlide + 1
      }
      if (runningSlide > 2) {
        runningSlide = 0
      }
      this.setState({ currentExperienceSlide: runningSlide })
    }, 3000)
    return () => {
      clearInterval(slide)
    }
  }

  render () {
    return (
      <SectionWrapper>
        <section className='section__container'>
          <p className='section__sub-heading'>
            Kami ingin kamu memiliki pengalaman <br /> yang menyenangkan dalam berasuransi dengan:
          </p>
          <div className='section__slider-main'>
            {
              this.props.ExperienceContentFull.map((data, index) => (
                <div className={'section__flex-container--img' + ((this.state.currentExperienceSlide === index) ? '' : ' section__flex-container--img--display-none')}>
                  <img src={data.img} alt={data.label} />
                </div>
              ))
            }
          </div>
        </section>
      </SectionWrapper>
    )
  }
}

export default Experience
