import React from 'react'

import SectionWrapper from './index.style'

const MarketSection = (props) => {
  const contentRenderer = (content) => {
    // Array  | String
    // Should probably be a component
    if (Array.isArray(content)) {
      return (
        <ul className='section__flex-section--list'>
          {content.map(c => (
            <li className='section__flex-section--list-item'>
              {c}
            </li>
          ))}
        </ul>
      )
    } else {
      return (
        <div className='section__flex-section--text'>
          {content}
        </div>
      )
    }
  }

  return (
    <SectionWrapper>
      <section className='section__container'>
        <h1 className='section__heading'>
            Perjalanan <span className='section__theme-color'> PasarPolis </span>
        </h1>
        <div className='section__flex-container'>
          {
            props.MarketData.topContent.map((data, index) => (
              <div className='section__flex'>
                <div className={'section__flex-section section__flex-section--img ' + ((index % 2 === 0) ? 'section__flex-section--order2' : 'section__flex-section--img section__flex-section--order1')}>
                  <img src={data.img} alt={data.year} widyh='100%' />
                </div>
                <div className={'section__flex-section ' + ((index % 2 === 0) ? 'section__flex-section--order1' : 'section__flex-section--order2')}>
                  <div className='section__flex-section--heading'>
                    {data.year}
                  </div>
                  {contentRenderer(data.text)}
                </div>
              </div>
            ))
          }
          <div className='section__flex-section'>
            <div className='section__flex-section--img '>
              <img src={props.MarketData.bottomContent.img} alt='current' widyh='100%' />
            </div>
            <div className='section__flex-section--text'>
              {props.MarketData.bottomContent.text}
            </div>
          </div>
        </div>
      </section>
    </SectionWrapper>
  )
}

export default MarketSection
