import React from 'react'
import { CarouselWrapper } from './index.style'

const Carousel = ({
  slides = [1, 2, 3],
  current = 0
}) => {
  return (
    <CarouselWrapper current={current}>
      <div
        className='slides-wrapper flex-container'
      >
        {
          slides.map((slide, index) => (
            <div className='slide' key={index}>
              {slide}
            </div>
          ))
        }
      </div>
    </CarouselWrapper>
  )
}
export default Carousel
