import AboutWrapper from '../About2/index.style'

import MainSection from '../About2/component/01MainSection'
import Leaders from '../About2/component/02Leaders'
import MarketSection from '../About2/component/03MarketSection'
import Innovation from '../About2/component/04Innovation'
import VisionMissionSection from '../About2/component/05VisionMissionSection'
import ExperienceSection from '../About2/component/06ExperienceSection'
import MarketImpact from '../About2/component/06MarketImpact'

import { MainSectionContent, leaders, Market, ExperienceContentFull } from '../About2/constant'

import Footer from '../../../components/Footer/footer'

class AboutUs extends Component {
  constructor (props) {
    super(props)
    this.state = {
      current: 0
    }
  }
  render () {
    return (
      <React.Fragment>
        <AboutWrapper current={this.state.current}>
          <MainSection className='about__main-section'
            BgImages={MainSectionContent.BgImages}
            content={MainSectionContent.content}
          />
          <Leaders
            leadersData={leaders}
            heading='Manajemen'
            current={this.state.current}
            onIncrease={() => this.setState((e) => ({ current: e.current + 1 }))}
            onDecrease={() => this.setState((e) => ({ current: e.current - 1 }))}
            slides={1}
          />
          <MarketSection MarketData={Market} />
          {/* <Innovation /> */}
          <VisionMissionSection />
          <ExperienceSection ExperienceContentFull={ExperienceContentFull} />
          <MarketImpact />
        </AboutWrapper>
        <Footer />
      </React.Fragment>
    )
  }
}

export default AboutUs
