import React from 'react'

const Leaders = (props) => {
  return (
    <section className='about__container'>
      <h1 className='about__heading'>
        {props.heading}
      </h1>
      <div className='about__leader-section--container'>
        <div className='about__leader-section about__slider-animation'>
          {
            props.leadersData.leaders.map(data => (
              <div className='about__leader-section--card'>
                <img src={data.img} alt={data.label} width='100%' />
              </div>
            ))
          }
        </div>
        {
          props.current < props.slides &&
          <div className='about__slider-button' onClick={() => props.onIncrease()}>
            <div className='about__slider-button--arrow' />
          </div>
        }
        {
          props.current > 0 &&
          <div className='about__slider-button--reverse' onClick={() => props.onDecrease()}>
            <div className='about__slider-button--reverse--arrow' />
          </div>
        }
      </div>
    </section>
  )
}

export default Leaders
